// The whole part stays a float so large magnitudes do not overflow an int.
fn fixed6(x float) String
    let neg = x < 0.0
    let mag = abs(x)
    var whole = floor(mag)
    var frac = floor((mag - whole) * 1000000.0 + 0.5) as int
    if frac == 1000000
        frac = 0
        whole = whole + 1.0
    // A float's string form is its exact digits with a trailing ".0".
    let digits = f"{whole}"
    let whole_str = digits.substring(0, digits.length() - 2)
    let frac_str = f"{frac}"
    let padded = "0".repeat(6 - frac_str.length()) + frac_str
    let sign = if neg and (whole > 0.0 or frac > 0): "-" else: ""
    f"{sign}{whole_str}.{padded}"

